const postsData = $input.first().json;
const subsData = $('Get Subscriber Count').first().json;

const posts = postsData.data || postsData.posts || [];
const totalSubs = subsData.total_results || subsData.pagination?.total || 0;

// Calculate stats
let totalOpenRate = 0;
let totalClickRate = 0;
let bestPost = null;
let worstPost = null;
let maxOpen = 0;
let minOpen = 100;

const postLines = posts.map(post => {
  const stats = post.stats || post.email_stats || {};
  const openRate = stats.open_rate || stats.unique_open_rate || 0;
  const clickRate = stats.click_rate || stats.unique_click_rate || 0;
  const subject = post.subject || post.title || 'Untitled';
  const recipients = stats.recipients || stats.total_sent || 0;

  totalOpenRate += openRate;
  totalClickRate += clickRate;

  if (openRate > maxOpen) { maxOpen = openRate; bestPost = subject; }
  if (openRate < minOpen && openRate > 0) { minOpen = openRate; worstPost = subject; }

  return `  • "${subject.substring(0, 50)}" → ${openRate.toFixed(1)}% opens | ${clickRate.toFixed(1)}% clicks`;
});

const avgOpen = posts.length > 0 ? (totalOpenRate / posts.length).toFixed(1) : '0';
const avgClick = posts.length > 0 ? (totalClickRate / posts.length).toFixed(1) : '0';

const openEmoji = parseFloat(avgOpen) >= 40 ? '🔥' : parseFloat(avgOpen) >= 30 ? '✅' : '📉';
const week = new Date().toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'Asia/Ho_Chi_Minh' });

const report = `📊 *Báo Cáo Newsletter Tuần — ${week}*
━━━━━━━━━━━━━━━━━━━━

👥 *Tổng subscribers:* ${totalSubs.toLocaleString()}
${openEmoji} *Avg open rate:* ${avgOpen}% (benchmark: 40%+)
🔗 *Avg click rate:* ${avgClick}% (benchmark: 3%+)
📧 *Emails tracked:* ${posts.length}

*📬 Chi tiết từng email:*
${postLines.join('\n') || '  Chưa có dữ liệu'}

${bestPost ? `🏆 *Best:* "${bestPost.substring(0,50)}" → ${maxOpen.toFixed(1)}%` : ''}
${worstPost ? `📉 *Needs work:* "${worstPost.substring(0,50)}" → ${minOpen.toFixed(1)}%` : ''}

━━━━━━━━━━━━━━━━━━━━
💬 Reply với feedback để cập nhật nội dung tháng tới!
Format: *feedback: [nhận xét của bạn]*`;

return [{ json: { report } }];
